        def _uncached_match(self, text, pos, cache, error):
            result = (callable(text, pos) if is_simple else
                      callable(text, pos, cache, error, grammar))

            if result is None:
                return None
            elif isinstance(result, int):
                if result < 0:  # -1 indicates no match
                    return None
                end, children = result, None
            elif isinstance(result, tuple):
                end, children = result
                if end < 0:  # -1 indicates no match
                    return None
            else:
                # Node or None
                return result
            return Node(self, text, pos, end, children=children)"}}

