        # First try direct access to each layer
        try:
            if key in self.layers:
                return True
        except (TypeError, IndexError, KeyError, Exception):
            pass

        try:
            if isinstance(key, tuple) and key[0] in self.layers:
                return key in self.layers[key[0]]
        except (TypeError, IndexError, KeyError, Exception):
            pass

        # Fall back to checking each layer
        for layer in self.layers.values():
            try:
                if key in layer:
                    return True
            except (TypeError, IndexError, KeyError, Exception):
                # Skip layers that don't support containment check
                pass

        return False

