class DirectConnectLag:
    """DirectConnect LAG model."""

    def __init__(
        self,
        location: str,
        connections_bandwidth: str,
        lag_name: str,
        number_of_connections: int,
        request_mac_sec: bool = False,
    ):
        """Initialize a DirectConnect LAG."""
        self.lag_id = f"dxlag-moto-{random_string(8)}"
        self.location = location
        self.connections_bandwidth = connections_bandwidth
        self.lag_name = lag_name
        self.lag_state = "available"
        self.mac_sec_capable = request_mac_sec
        self.mac_sec_keys = []
        self.encryption_mode = "must_encrypt" if request_mac_sec else "no_encrypt"
        self.connections: List[DirectConnectConnection] = []

        # Create the requested number of connections
        for i in range(number_of_connections):
            conn = DirectConnectConnection(
                location=location,
                bandwidth=connections_bandwidth,
                connection_name=f"Requested Connection {i+1} for Lag {self.lag_id}",
                request_mac_sec=request_mac_sec,
            )
            conn.lag_id = self.lag_id
            self.connections.append(conn)

    def to_dict(self) -> dict:
